    if(oldEpoch){for(const row of this.db.prepare("SELECT * FROM protocol_operations WHERE room_epoch=? AND state='accepted'").all(oldEpoch)){const receipt=json<ProtocolReceipt>(row.receipt);this.finishReceipt(row,{...receipt,state:'rejected',effectCommitted:false,code:'ROOM_EPOCH_CHANGED',receiptVersion:incrementProtocolCounter(receipt.receiptVersion),updatedAt:this.now()});}this.db.prepare('UPDATE protocol_epochs SET active=0 WHERE room_epoch=?').run(oldEpoch);this.db.prepare('UPDATE protocol_grants SET revoked=1 WHERE room_epoch=?').run(oldEpoch);}
