    for(let player=0;player<players;player++){const initial=cursor(),mapping=options.subjectMapping?.find(m=>m.newPlayer===player),subject=mapping?String(oldPlayers.find(row=>row.player===mapping.oldPlayer)!.subject_id):randomUUID();this.db.prepare('INSERT INTO protocol_players(room_epoch,player,stream_epoch,seq,head_cursor,initial_cursor,decision_version,generation,subject_id) VALUES(?,?,?,?,?,?,?,?,?)').run(epoch,player,randomUUID(),'0',initial,initial,randomUUID(),'0',subject);}
