  currentEpoch(roomId:string){const row=this.db.prepare('SELECT room_epoch FROM protocol_epochs WHERE room_id=? AND active=1').get(roomId);if(!row)throw Error('No current protocol epoch');return String(row.room_epoch);}
  scope(roomId:string,roomEpoch:string,player:number):ProtocolScope{return{serverId:this.serverId,roomId,roomEpoch,playerId:`player-${String(this.seat(roomEpoch,player).subject_id)}`};}
  private seat(roomEpoch:string,player:number){const row=this.db.prepare('SELECT * FROM protocol_players WHERE room_epoch=? AND player=?').get(roomEpoch,player);if(!row)throw new PlayerProtocolError('IDENTITY_MISMATCH',403,'Player identity is unavailable','authorization');return row;}
  /** Provisioning mechanism only. Production callers must establish owner authorization; development tests use temporary synthetic tokens. */
